export interface ClaimMatch {
  category: string;
  matchedPhrase: string;
  expectedTool: string;
  /**
   * The sentence or clause containing `matchedPhrase` (mt#3198).
   *
   * SEPARATE from `matchedPhrase` on purpose. `matchedPhrase` is the diversity
   * axis the calibration sweep keys on — `extractDistinctPhrases` in
   * `src/domain/calibration/calibration-sweep.ts` derives `matchedPhrases`
   * from `matches[].phrase`, so widening THAT field would make every record a
   * distinct "phrase" (sentences are near-unique) and silently destroy the
   * distinct-count that drives the review-due threshold.
   */
  context: string;
}

/**
 * Reason strings for this detector's suppression gate (mt#3207).
 *
 * The gate has sources with different FP profiles, so they get different
 * reasons: a same-turn tool call is proof the claim was backed as it was
 * written, while a trailing-window hit (mt#2671) is the weaker back-reference
 * inference. A calibration reviewer needs to tell them apart from the record
 * alone.
 *
 * PR #3096 R3 (non-blocking) added the third. Identity-scoped suppression is a
 * DIFFERENT condition from the other two — not `requiredTools` presence but a
 * read of the PR the claim NAMES — and recording it as `window-tool-call` made
 * the two indistinguishable in the log, which is the thing this docblock says
 * must not happen. Its FP profile is its own: it is the only source that can be
 * defeated by a claim naming the wrong number.
 */
export const SUPPRESSION_SAME_TURN_TOOL_CALL = "same-turn-tool-call";
export const SUPPRESSION_WINDOW_TOOL_CALL = "window-tool-call";
export const SUPPRESSION_IDENTITY_SCOPED_TOOL_CALL = "identity-scoped-tool-call";
/**
 * Identity-scoped, with the PR number read from the claim's SENTENCE rather
 * than its matched phrase (mt#4810). A distinct reason so a calibration
 * reviewer can measure THIS path's own delta: an unchanged headline count is
 * equally consistent with "the fallback is inert" and "it fires and something
 * else absorbs it", and only the per-reason split separates them (mem#1208).
 */
export const SUPPRESSION_IDENTITY_SCOPED_CONTEXT = "identity-scoped-context";

/** A claim that matched its category's patterns but was backed by a real tool call. */
export interface SuppressedClaimMatch extends ClaimMatch {
  /** One of the SUPPRESSION_* reason strings above. */
  reason: string;
}

/** Both halves of one detection pass: what fired, and what a gate swallowed. */
export interface PreNarrationDetection {
  /** Unbacked claims — these inject. */
  matches: ClaimMatch[];
  /** Backed claims — detected, then suppressed. Recorded, never injected. */
  suppressed: SuppressedClaimMatch[];
}

/**
 * Elide markdown contexts that carry quoted text rather than the agent's own
 * assertions (inline code spans, fenced code blocks, blockquotes). Replaces
 * matched content with same-length whitespace to preserve character positions.
 * This avoids firing on quoted tool output the agent pasted (e.g. "200 OK"
 * inside a code fence).
 */
export function elideMarkdownContexts(text: string): string {
  let result = text;
  result = result.replace(/^[ \t]{0,3}(`{3,}|~{3,})[^\n]*\n[\s\S]*?\n[ \t]{0,3}\1[ \t]*$/gm, (m) =>
    " ".repeat(m.length)
  );
  result = result.replace(/(`+)([^`]|(?!`)[^`]*?)\1(?!`)/g, (m) => " ".repeat(m.length));
  result = result.replace(/^[ \t]{0,3}>+.*$/gm, (m) => " ".repeat(m.length));
  return result;
}

