// ---------------------------------------------------------------------------
// Detection (pure, exported for testing)
// ---------------------------------------------------------------------------

/**
 * Collect tool_use names appearing in the trailing window of the transcript:
 * the last `windowTurns` turns (segments delimited by real user prompts),
 * INCLUDING the current turn. Walks backwards counting real-user-prompt
 * boundaries and extracts tool_use names from everything after the cutoff.
 *
 * Used for cross-turn suppression (mt#2671): a claim whose backing tool call
 * ran in a recent prior turn is a legitimate back-reference, not
 * pre-narration.
 */
export function windowSlice(lines: TranscriptLine[], windowTurns: number): TranscriptLine[] {
  let boundaries = 0;
  let start = 0;
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i];
    if (line !== undefined && isRealUserPrompt(line)) {
      boundaries++;
      if (boundaries >= windowTurns) {
        start = i;
        break;
      }
    }
  }
  return lines.slice(start);
}

/**
 * Tool names as observed, PLUS each one's bare suffix (mt#4498).
 *
 * `requiredTools` is matched with exact `Set.has`, and this project runs more
 * than one MCP server alias for the same server: a session connected as
 * `minsky-server` emits `mcp__minsky-server__session_pr_merge`, which equals
 * neither the `mcp__minsky__…` entry nor the bare `session_pr_merge` entry that
 * every list already carries. The suppressor could therefore never see that
 * session's evidence, and every result claim in it fired as pre-narration.
 *
 * Registering the suffix makes the bare entries — already present in all four
 * categories — do the work, so no list needs a second copy per alias and a
 * future alias is covered without another edit.
 *
 * Measured share of the residual, so this is not mistaken for the headline: 2 of
 * 65 tool-absent leaks (3%). It is a correctness fix, not the cause.
 *
 * Only the LAST segment is added, so `mcp__github__pull_request_read` also
 * registers `pull_request_read` — which the lists already treat as equivalent.
 */
export function bareToolName(name: string): string {
  return name.split("__").pop() ?? name;
}

export function withBareToolAliases(names: Iterable<string>): Set<string> {
  const out = new Set<string>();
  for (const name of names) {
    out.add(name);
    const bare = bareToolName(name);
    if (bare !== name) out.add(bare);
  }
  return out;
}

export function extractWindowToolUseNames(
  lines: TranscriptLine[],
  windowTurns: number
): Set<string> {
  return withBareToolAliases(extractToolUseNames(windowSlice(lines, windowTurns)));
}

/**
 * PR numbers each category's `identityScopedTools` were called against, WITHIN
 * the same window the tool-name set covers (PR #3096 R2).
 *
 * Both halves of identity-scoped suppression must share one scope. The first
 * version gathered PR numbers over the WHOLE transcript while gating on a
 * scoped tool having run in-window — two different scopes, which let an old
 * read of the claimed PR combine with an unrelated recent read to suppress.
 * The reviewer caught it; deriving the numbers from `windowSlice` is what makes
 * the two conditions one condition.
 *
 * Keyed BY CATEGORY so a scoped tool declared on one category cannot back a
 * claim in another. Only `merged` declares any today, so this is a latent
 * distinction rather than a live one — encoded now because the union form is
 * indistinguishable from correct until a second category exists.
 */
export function buildIdentityEvidence(
  lines: TranscriptLine[],
  windowTurns: number
): Map<string, ReadonlySet<number>> {
  const slice = windowSlice(lines, windowTurns);
  const byCategory = new Map<string, ReadonlySet<number>>();
  for (const category of OUTCOME_CATEGORIES) {
    const scoped = category.identityScopedTools ?? [];
    if (scoped.length === 0) continue;
    byCategory.set(category.key, extractPrNumbersForTools(slice, scoped));
  }
  return byCategory;
}

/**
 * Detect pre-narrated tool outcomes in an assistant turn.
 *
 * For each outcome category, if a completion-shaped claim pattern matches the
 * assistant prose AND none of the category's requiredTools appear in the turn's
 * tool_use names, the category fires. Quoted/code-span text is elided first to
 * reduce false positives on pasted tool output.
 *
 * Cross-turn suppression (mt#2671): when `windowToolNames` is provided (the
 * tool_use names from the trailing TRAILING_WINDOW_TURNS turns), a category
 * whose requiredTools appear anywhere in that window is also treated as
 * backed — a legitimate back-reference to a result fetched in a recent prior
 * turn ("the bot APPROVED", summarizing an earlier session_pr_wait-for-review)
 * must not fire. Omitting the parameter preserves same-turn-only semantics.
 *
 * Returns one ClaimMatch per fired category (deduplicated by category).
 */
export function detectPreNarration(
  turnLines: TranscriptLine[],
  windowToolNames?: ReadonlySet<string>,
  evidencePrNumbers?: ReadonlyMap<string, ReadonlySet<number>>
): ClaimMatch[] {
  return detectPreNarrationWithSuppression(turnLines, windowToolNames, evidencePrNumbers).matches;
}

/**
 * The same pass as `detectPreNarration`, keeping BOTH halves (mt#3207).
 *
 * The pattern scan now runs BEFORE the backed-by-tool check rather than after
 * it. Previously a backed category was `continue`d before its patterns were
 * ever tested, so a suppressed claim and a turn that made no claim at all
 * produced identical output — nothing. Running the patterns first costs one
 * regex pass per backed category and is what makes the gate measurable.
 */
export function detectPreNarrationWithSuppression(
  turnLines: TranscriptLine[],
  windowToolNames?: ReadonlySet<string>,
  /**
   * Per-category PR numbers the `identityScopedTools` were called against,
   * within the SAME window `windowToolNames` covers. Build it with
   * `buildIdentityEvidence`. Omitting it disables identity-scoped suppression
   * entirely — the safe direction for a suppressor.
   */
  evidencePrNumbers?: ReadonlyMap<string, ReadonlySet<number>>
): PreNarrationDetection {
  const rawText = extractAssistantText(turnLines);
  if (!rawText) return { matches: [], suppressed: [] };

  // Double-quoted prose elided AFTER the markdown pass (mt#3864 class 6), so
  // quotes inside a code span are already blanked and cannot confuse pairing —
  // the same ordering `elideQuotedAndCodeContexts` uses.
  const text = elideDoubleQuotedSpans(elideMarkdownContexts(rawText));
  const toolNames = withBareToolAliases(extractToolUseNames(turnLines));

  const matches: ClaimMatch[] = [];
  const suppressed: SuppressedClaimMatch[] = [];
  for (const category of OUTCOME_CATEGORIES) {
    let matched: ClaimMatch | undefined;
    for (const pattern of category.patterns) {
      const m = pattern.exec(text);
      if (m) {
        matched = {
          category: category.key,
          matchedPhrase: safeTruncate(m[0], MATCHED_PHRASE_MAX_CHARS, "head"),
          expectedTool: category.expectedTool,
          // `text` is the ELIDED text the match ran against — see
          // extractMatchContext's contract for why that matters.
          context: extractMatchContext(text, m.index, m[0].length),
        };
        break; // one match per category is enough
      }
    }
    if (!matched) continue;

    // Backed by a real tool call — this turn, or in the trailing window
    // (mt#2671). Same-turn wins when both hold: it is the stronger evidence.
    const sameTurn = category.requiredTools.some((t) => toolNames.has(t));
    const inWindow = category.requiredTools.some((t) => windowToolNames?.has(t) ?? false);

    // Identity-scoped evidence (PR #3096 R1/R2): a READ, in the window, OF THE
    // PR the claim names. ONE condition in ONE scope — R2 flagged that the
    // earlier form gated on "a scoped tool ran in-window" while sourcing PR
    // numbers from the whole transcript, so an old read of the claimed PR could
    // ride in on an unrelated recent one. `buildIdentityEvidence` derives the
    // numbers from the same `windowSlice`, which collapses the two into one.
    //
    // A claim naming no PR number is never identity-backed and deliberately
    // falls through to firing.
    // mt#4810: the phrase is the tightest subject when it carries one — mt#4498
    // put the number there for the `PR #N … APPROVED` shape. When it does not,
    // fall back to the claim's own sentence, which the record has captured as
    // `context` since mt#3198 and which nothing was reading. Measured over the
    // full calibration corpus, that is 22 of 31 with-context `review-approved`
    // fires whose phrase is the bare `APPROVED` token.
    const phrasePr = extractClaimedPrNumber(matched.matchedPhrase);
    const contextPr = phrasePr === null ? extractUniqueClaimedPrNumber(matched.context) : null;
    const claimedPr = phrasePr ?? contextPr;
    const identityBacked =
      claimedPr !== null && (evidencePrNumbers?.get(category.key)?.has(claimedPr) ?? false);

    if (sameTurn || inWindow || identityBacked) {
      // Ordered by strength of evidence, so the recorded reason names the
      // source that actually carried the suppression: a same-turn call is the
      // strongest, and identity-scoped is only reached when NO `requiredTools`
      // call was present at all — which is precisely the case a calibration
      // reviewer needs to see distinctly (PR #3096 R3).
      suppressed.push({
        ...matched,
        reason: sameTurn
          ? SUPPRESSION_SAME_TURN_TOOL_CALL
          : inWindow
            ? SUPPRESSION_WINDOW_TOOL_CALL
            : contextPr !== null
              ? SUPPRESSION_IDENTITY_SCOPED_CONTEXT
              : SUPPRESSION_IDENTITY_SCOPED_TOOL_CALL,
      });
      continue;
    }
    matches.push(matched);
  }
  return { matches, suppressed };
}

/**
 * One calibration record for a detection pass (mt#3207).
 *
 * `matches` carries BOTH halves so a suppressed fire stays classifiable —
 * `hadMatchingTool` (already in the shape, previously hard-coded `false`) is
 * now the per-claim discriminator. Top-level `suppressionReasons` is the
 * shared contract `isSuppressedRecord` reads: populated only when the pass
 * injected NOTHING, because a record with even one live match is a fire the
 * operator saw and must count as injected.
 *
 * `context` (mt#3198) is what makes a record classifiable by a HUMAN rather
 * than only by the machine. `hadMatchingTool` answers "was a backing tool call
 * present"; it cannot answer "was this a claim at all". The bare phrase
 * `merged PR` is equally consistent with pre-narration ("I merged the PR") and
 * with ordinary retrospective reference ("the merged PR touches X") — the
 * dominant false-positive shape in this log, and indistinguishable without the
 * surrounding sentence. Added as a NEW key; `phrase` keeps its exact prior
 * meaning because the calibration sweep's diversity axis is keyed on it.
 */
export function buildPreNarrationRecord(
  sessionId: string | undefined,
  detection: PreNarrationDetection
): Record<string, unknown> {
  const suppressionReasons =
    detection.matches.length === 0
      ? [...new Set(detection.suppressed.map((s) => s.reason))].sort()
      : [];
  return {
    timestamp: new Date().toISOString(),
    session_id: sessionId,
    // mt#4286: mirrors `ask-routing-deferral-detector.ts`. Without it a reviewer
    // cannot tell a quiet window from a live one, and every record in the log
    // predating the mt#4286 flip looks identical to one written after it.
    injection_enabled: INJECTION_ENABLED,
    // mt#3607: this surface has captured its judged input since mt#3198; the
    // marker says so explicitly, so a corpus-wide auditability check reads the
    // same field everywhere instead of special-casing the surfaces that shipped
    // capture before the marker existed.
    [CAPTURE_SCHEMA_FIELD]: CAPTURE_SCHEMA_VERSION,
    matches: [
      ...detection.matches.map((m) => ({
        category: m.category,
        phrase: m.matchedPhrase,
        context: m.context,
        expectedTool: m.expectedTool,
        hadMatchingTool: false,
      })),
      ...detection.suppressed.map((m) => ({
        category: m.category,
        phrase: m.matchedPhrase,
        context: m.context,
        expectedTool: m.expectedTool,
        hadMatchingTool: true,
        suppressionReason: m.reason,
      })),
    ],
    suppressionReasons,
  };
}

// ---------------------------------------------------------------------------
// Calibration logging (mirrors retrospective-trigger-scanner.ts)
// ---------------------------------------------------------------------------

function appendCalibrationRecord(cwd: string, record: Record<string, unknown>): void {
  // mt#4752: the shared helper derives the path from the stream NAME, so the
  // filename cannot drift from the convention the .gitignore globs encode.
  // `cwd` is the guard's raw input cwd — a FALLBACK, never an authoritative
  // root (see `calibrationLogPath`'s docblock for why the two ranks differ).
  logCalibrationRecord(CALIBRATION_LOG_NAME, record, { fallbackCwd: cwd });
}

// ---------------------------------------------------------------------------
// Reminder builder
// ---------------------------------------------------------------------------

/**
 * Advisory-text provenance, kept here rather than in the injection per
 * `.minsky/rules/guard-feedback-authoring.mdc` (mt#3485): the detector is
 * mt#2197 and the anti-pattern it targets is memory `30f5d164` — narrating a
 * result (PR created, review approved, merged, build clean, HTTP 200) before
 * the result is in hand.
 *
 * The claim taxonomy that used to be enumerated inline lives in
 * `CLAIM_PATTERNS` above, which is both the authority and the source of the
 * matched-claim evidence lines — restating it in the injection told the agent
 * nothing the evidence lines did not already say more precisely.
 */
function buildReminder(matches: ClaimMatch[]): string {
  const lines = matches
    .map(
      (m) =>
        `- **${m.category}**: claim "${m.matchedPhrase}" with no matching tool result this turn (expected: \`${m.expectedTool}\`)`
    )
    .join("\n");

  return [
    "[pre-narration-detector] The previous turn asserted a tool outcome with no",
    "matching tool call in the same turn.",
    "",
    "**Matched claims:**",
    lines,
    "",
    "Run the minting tool and READ its real result this turn before restating the",
    "outcome — in chat or in a durable artifact. If it did occur in an earlier turn,",
    "cite the tool result you are relying on.",
    "",
    "If the claim was legitimate — the tool ran earlier, or the phrase was a quote",
    "or an example — no action is needed.",
  ].join("\n");
}

/**
 * The largest `additionalContext` this guard could emit, for
 * `guard-feedback-shape.test.ts`'s size-ceiling check (mt#4002 pattern).
 *
 * Required because mt#4286 quieted this guard: a guard that renders nothing on
 * the live path has its declared ceiling enforced against the empty string,
 * which is the blind spot mt#4002 found on five guards at once (declared
 * 400-1650, all measuring 0, five of six understated by up to 3.6x).
 *
 * **This is a proved CEILING, not a saturated sample** — unlike its siblings on
 * `causal-premise` and `operator-deferral`, whose count axes are unbounded.
 * `detectPreNarrationWithSuppression` emits at most ONE match per category
 * ("one match per category is enough"), so the count axis is bounded by
 * `OUTCOME_CATEGORIES.length`, and each phrase is capped at
 * `MATCHED_PHRASE_MAX_CHARS` by `safeTruncate`. `context` is recorded but never
 * rendered here, so it does not enter the bound. Both axes are therefore posed
 * at their true maxima below.
 *
 * Measured at 1753 chars when this shipped, against a declared 650 — that 650
 * came from the ONE-match canary (581 chars), which is not this guard's worst
 * case. Adding a category or raising the phrase cap moves this; the test reads
 * the render rather than a literal, so it re-derives itself.
 */
export function renderWorstCase(): string {
  const phrase = "x".repeat(MATCHED_PHRASE_MAX_CHARS);
  return buildReminder(
    OUTCOME_CATEGORIES.map((category) => ({
      category: category.key,
      matchedPhrase: phrase,
      expectedTool: category.expectedTool,
      context: "",
    }))
  );
}

// ---------------------------------------------------------------------------
// Dispatcher-compatible pure function (ADR-028 D1/D2 — mt#2652 Phase 2a)
// ---------------------------------------------------------------------------

/**
 * Guard-dispatcher entry point. Mirrors `main()`'s orchestration but returns
 * a `GuardOutcome` instead of writing to stdout/`process.exit`. Reuses
 * `ctx.transcriptLines` (D6) instead of re-parsing the transcript itself.
 * Always injects `additionalContext` on a match (this detector is not
 * calibration-gated, unlike causal-premise / code-mechanism-assertion /
 * ask-routing-deferral) and always logs a calibration record too.
 */
export function run(input: ClaudeHookInput, ctx: DispatchContext): GuardOutcome | null {
  const overrideVal = process.env[OVERRIDE_ENV_VAR];
  const isOverride =
    overrideVal === "1" ||
    overrideVal?.toLowerCase() === "true" ||
    overrideVal?.toLowerCase() === "yes";

  if (isOverride) {
    return {
      auditLines: [
        `[pre-narration-detector] OVERRIDE: ack=${overrideVal} session=${input.session_id ?? "unknown"} ts=${new Date().toISOString()}\n`,
      ],
    };
  }

  if (!input.transcript_path) return null;
  const lines = ctx.transcriptLines;
  if (lines.length === 0) return null;

  let detection: PreNarrationDetection;
  try {
    const turnLines = extractLastAssistantTurn(lines, ctx.recordedAnchor);
    if (turnLines.length === 0) return null;
    // Cross-turn suppression (mt#2671): window computed from ctx.transcriptLines
    // per the guard-module contract (mt#2637) — never re-derived.
    const windowToolNames = extractWindowToolUseNames(lines, TRAILING_WINDOW_TURNS);
    const evidencePrNumbers = buildIdentityEvidence(lines, TRAILING_WINDOW_TURNS);
    detection = detectPreNarrationWithSuppression(turnLines, windowToolNames, evidencePrNumbers);
  } catch (err) {
    process.stderr.write(
      `[pre-narration-detector] Detection error: ${err instanceof Error ? err.message : String(err)}\n`
    );
    return null;
  }

  // mt#3207: a pass with ONLY suppressed claims still records — that is the
  // gap this task closes. Nothing detected at all still stays silent.
  if (detection.matches.length === 0 && detection.suppressed.length === 0) return null;

  const outcome: GuardOutcome = {
    calibration: buildPreNarrationRecord(input.session_id, detection),
  };
  if (INJECTION_ENABLED && detection.matches.length > 0) {
    outcome.additionalContext = buildReminder(detection.matches);
  }
  return outcome;
}

// ---------------------------------------------------------------------------
// Entrypoint
// ---------------------------------------------------------------------------

/**
 * Main hook function. Reads ClaudeHookInput from stdin, inspects the just-completed
 * assistant turn, and emits an additionalContext reminder when a pre-narrated
 * outcome is detected. Always exits 0 (fail-open, informational only).
 */
export async function main(): Promise<void> {
  const overrideVal = process.env[OVERRIDE_ENV_VAR];
  const isOverride =
    overrideVal === "1" ||
    overrideVal?.toLowerCase() === "true" ||
    overrideVal?.toLowerCase() === "yes";

  let input: ClaudeHookInput;
  try {
    input = await readInput<ClaudeHookInput>();
  } catch {
    process.exit(0);
  }

  if (isOverride) {
    const ts = new Date().toISOString();
    process.stdout.write(
      `[pre-narration-detector] OVERRIDE: ack=${overrideVal} session=${input.session_id ?? "unknown"} ts=${ts}\n`
    );
    process.exit(0);
  }

  const transcriptPath = input.transcript_path;
  if (!transcriptPath) {
    process.exit(0);
  }

  let lines: TranscriptLine[];
  try {
    lines = resolveParentTranscriptLinesForPath(transcriptPath, input.agent_id);
  } catch (err) {
    console.error(
      `[pre-narration-detector] Failed to read transcript: ${err instanceof Error ? err.message : String(err)}`
    );
    process.exit(0);
  }

  if (lines.length === 0) {
    process.exit(0);
  }

  let detection: PreNarrationDetection;
  try {
    const turnLines = extractLastAssistantTurn(lines);
    if (turnLines.length === 0) {
      process.exit(0);
    }
    // Cross-turn suppression (mt#2671): scan the trailing window for backing
    // tool calls so legitimate back-references don't fire.
    const windowToolNames = extractWindowToolUseNames(lines, TRAILING_WINDOW_TURNS);
    const evidencePrNumbers = buildIdentityEvidence(lines, TRAILING_WINDOW_TURNS);
    detection = detectPreNarrationWithSuppression(turnLines, windowToolNames, evidencePrNumbers);
  } catch (err) {
    console.error(
      `[pre-narration-detector] Detection error: ${err instanceof Error ? err.message : String(err)}`
    );
    process.exit(0);
  }

  if (detection.matches.length === 0 && detection.suppressed.length === 0) {
    process.exit(0);
  }

  appendCalibrationRecord(input.cwd, buildPreNarrationRecord(input.session_id, detection));

  // mt#3207: suppressed-only passes record but never inject (mirrors `run()`).
  // mt#4286: and while the posture is log-only, NO pass injects — the record
  // above is written either way, which is the whole point of the quieting.
  if (!INJECTION_ENABLED || detection.matches.length === 0) {
    process.exit(0);
  }

  const reminder = buildReminder(detection.matches);
  const output: HookOutput = {
    hookSpecificOutput: {
      hookEventName: "UserPromptSubmit",
      additionalContext: reminder,
    },
  };
  process.stdout.write(JSON.stringify(output));
  process.exit(0);
}

if (import.meta.main) {
  main();
}
